    if sig:
        i=INFO.get(sig,{})
        d['evidence']=dict(method_signature=sig,dex=i.get('dex'),
            code_offset=i.get('code_offset'),instructions=i.get('instructions'),
            callers=i.get('callers'),callees=i.get('callees'))
    else: d['evidence']={}
    d['evidence'].update(kw.pop('evidence',{}))
    d.update(kw)
    E.append(d)
